/* Event and cosmetic definition editor. Protected roles are rechecked by Postgres. */
(() => {
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let owner='',definitions=[],editing=null,busy=false,epoch=0,selected=new Set();
 const allowed=()=>{const a=window.KizunaAccount?.getSnapshot?.();return a?.isAdmin===true&&!a.loading&&!!a.user?.id;};
 const root=()=>document.getElementById('ks-adventure');
 const status=text=>{const n=document.getElementById('kaStaffStatus');if(n)n.textContent=text;};
 const dateInput=value=>value?new Date(value).toISOString().slice(0,16):'';
 function mount(){
  const host=document.getElementById('staffPage');
  if(!allowed()){document.getElementById('kaStaffTab')?.remove();root()?.remove();definitions=[];selected.clear();owner='';epoch++;return;}
  const nextOwner=window.KizunaAccount.getSnapshot().user.id;
  if(owner&&nextOwner!==owner){document.getElementById('kaStaffTab')?.remove();root()?.remove();definitions=[];selected.clear();editing=null;busy=false;epoch++;}
  if(!host||root())return;
  owner=window.KizunaAccount.getSnapshot().user.id;
  const tab=document.createElement('button');tab.type='button';tab.id='kaStaffTab';tab.dataset.ksTab='adventure';tab.textContent='Liens & missions';tab.setAttribute('aria-controls','ks-adventure');tab.setAttribute('aria-pressed','false');host.querySelector('.ks-tabs').append(tab);
  const panel=document.createElement('section');panel.id='ks-adventure';panel.className='ks-panel ka-staff';panel.hidden=true;panel.innerHTML='<header><span class="ka-kicker">FAIRE VIVRE KIZUNA</span><h2>Liens, défis et rendez-vous</h2><p>Publie des constellations vérifiées, des missions et des annonces. Les événements se gèrent dans Anomalies. Les récompenses sont des titres, badges ou décorations. Désactiver une définition conserve les récompenses déjà obtenues.</p></header><p id="kaStaffStatus" class="ka-staff-status" role="status"></p><div class="ka-actions"><button type="button" class="ks-button" data-ka-admin="new">Nouvelle définition</button><button type="button" class="ks-button ks-secondary" data-ka-admin="refresh">Actualiser</button></div><div id="kaDefinitionList" class="ka-definition-list"></div><form id="kaDefinitionForm"></form>';
  host.querySelector('.ks-wrap').append(panel);
  tab.addEventListener('click',()=>{host.querySelectorAll('.ks-panel').forEach(n=>n.hidden=n!==panel);host.querySelectorAll('.ks-tabs button').forEach(n=>{n.classList.toggle('is-active',n===tab);n.setAttribute('aria-pressed',String(n===tab));});load();});
  panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||busy)return;if(b.dataset.kaEdit){editing=definitions.find(d=>d.id===b.dataset.kaEdit);selected=new Set(editing.requirements.card_ids||[]);form();}if(b.dataset.kaAdmin==='new'){editing=null;selected.clear();form();}if(b.dataset.kaAdmin==='refresh')load();});
  panel.addEventListener('input',e=>{if(e.target.id==='kaDefinitionSearch')members(e.target.value);});
  panel.addEventListener('change',e=>{if(e.target.matches('[data-ka-definition-card]')){if(e.target.checked&&selected.size>=12){e.target.checked=false;status('Douze personnages maximum.');return;}e.target.checked?selected.add(e.target.value):selected.delete(e.target.value);document.getElementById('kaMemberCount').textContent=selected.size+' personnage(s) sélectionné(s)';}if(e.target.name==='kind'||e.target.name==='metric')fields();});
  panel.addEventListener('submit',submit);
 }
 function list(){document.getElementById('kaDefinitionList').innerHTML=definitions.map(d=>'<button type="button" data-ka-edit="'+esc(d.id)+'">'+esc(d.title)+' · '+(d.enabled?'Publié':'Désactivé')+'</button>').join('');}
 async function load(){if(busy||!allowed())return;busy=true;const token=++epoch;status('Chargement des définitions…');try{const r=await window.KizunaAccount.adventureRequest('get');if(token!==epoch||!allowed())return;definitions=r.definitions;list();if(!document.getElementById('kaDefinitionForm').children.length)form();status(definitions.length+' définition(s).');}catch(e){if(token===epoch)status(e.message);}finally{if(token===epoch)busy=false;}}
 function form(){const d=editing||{},r=d.requirements||{},cards=window.KizunaGame.getSnapshot().cards,universes=[...new Set(cards.map(c=>c.series))].sort((a,b)=>a.localeCompare(b,'fr'));document.getElementById('kaDefinitionForm').innerHTML='<h3>'+esc(d.title||'Nouvelle définition')+'</h3><div class="ka-form-grid"><label>Identifiant stable<input name="id" value="'+esc(d.id||'')+'" pattern="[a-z0-9][a-z0-9-]{1,79}" maxlength="80" placeholder="festival-des-liens" required '+(d.id?'readonly':'')+'></label><label>Type<select name="kind">'+[...(d.kind==='event'?[['event','Ancien événement · conservé']]:[]),['mission','Mission / succès'],['constellation','Constellation'],['announcement','Annonce']].map(([id,label])=>'<option value="'+id+'" '+(d.kind===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label class="wide">Titre<input name="title" minlength="2" maxlength="90" value="'+esc(d.title||'')+'" required></label><label class="wide">Description<textarea name="description" maxlength="1200">'+esc(d.description||'')+'</textarea></label><label>Univers<select name="universe"><option value="">Tous les univers</option>'+universes.map(u=>'<option '+(u===d.universe||u===r.universe?'selected':'')+'>'+esc(u)+'</option>').join('')+'</select></label><label>Périodicité<select name="period">'+[['once','Une seule fois'],['day','Quotidien · minuit UTC'],['week','Hebdomadaire · lundi UTC']].map(([id,label])=>'<option value="'+id+'" '+(d.period===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>Objectif<select name="metric">'+[['total','Cartes différentes possédées'],['cards','Personnages exacts'],['universe','Cartes d’un univers'],['visits','Univers visités'],['discoveries','Découvertes dans la période'],['constellations','Constellations complétées'],['awakenings','Cartes éveillées']].map(([id,label])=>'<option value="'+id+'" '+(r.metric===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>Quantité à atteindre<input name="goal" type="number" min="1" max="5000" step="1" value="'+esc(r.goal||5)+'" required></label><label>Début · UTC<input name="starts_at" type="datetime-local" value="'+dateInput(d.starts_at)+'"></label><label>Fin · UTC<input name="ends_at" type="datetime-local" value="'+dateInput(d.ends_at)+'"></label><label>Type de récompense<select name="reward_kind">'+[['badge','Badge'],['title','Titre'],['decoration','Insigne décoratif']].map(([id,label])=>'<option value="'+id+'" '+(d.reward_kind===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>Nom de la récompense<input name="reward_label" maxlength="90" value="'+esc(d.reward_label||'')+'" required></label><label class="wide">Source officielle de l’histoire<input name="source_url" type="url" pattern="https://.*" value="'+esc(d.source_url||'')+'" placeholder="https://…"></label></div><div id="kaDefinitionMembers"><label class="ka-filter">Choisir les personnages<input id="kaDefinitionSearch" type="search" placeholder="Nom ou anime"></label><p id="kaMemberCount">'+selected.size+' personnage(s) sélectionné(s)</p><div id="kaDefinitionCards" class="ka-staff-members"></div><p class="ka-note">Deux à douze personnages distincts. L’ordre sélectionné détermine les nœuds ; les liens voisins forment la constellation. Vérifie les relations dans la source officielle.</p><label>Nature du lien<input name="relation" maxlength="60" value="'+esc(r.edges?.[0]?.[2]||'Lien narratif vérifié')+'"></label></div><div class="ka-actions"><label><input type="checkbox" name="enabled" '+(d.enabled?'checked':'')+'> Publié</label><label><input type="checkbox" name="secret" '+(d.secret?'checked':'')+'> Succès secret</label></div><div class="ka-actions"><button class="ks-button" type="submit">Enregistrer la définition</button></div><p class="ka-note">Les champs de dates utilisent UTC. Aucun joueur, résultat ou événement actif n’est créé automatiquement.</p>';members();fields();}
 function fields(){const form=document.getElementById('kaDefinitionForm'),f=form.elements,kind=f.kind.value;if(kind==='constellation')f.metric.value='cards';f.metric.disabled=kind==='constellation';document.getElementById('kaDefinitionMembers').hidden=f.metric.value!=='cards';f.starts_at.required=kind==='event';f.ends_at.required=kind==='event';f.source_url.required=kind==='constellation';}
 function members(query=''){const rows=window.KizunaGame.getSnapshot().cards.filter(c=>(c.name+' '+c.series).toLocaleLowerCase('fr').includes(query.toLocaleLowerCase('fr'))).sort((a,b)=>Number(selected.has(b.id))-Number(selected.has(a.id))||a.name.localeCompare(b.name,'fr'));document.getElementById('kaDefinitionCards').innerHTML=rows.slice(0,60).map(c=>'<label><input type="checkbox" data-ka-definition-card value="'+esc(c.id)+'" '+(selected.has(c.id)?'checked':'')+'>'+esc(c.name)+' · '+esc(c.series)+'</label>').join('')+(rows.length>60?'<p>Affiner la recherche pour les autres personnages.</p>':'');}
 async function submit(event){event.preventDefault();if(busy||!allowed())return;const f=event.target.elements,ids=[...selected],metric=f.metric.value;
  if(metric==='cards'&&(ids.length<2||ids.length>12)){status('Choisis de deux à douze personnages.');return;}
  if(metric==='universe'&&!f.universe.value){status('Choisis un univers pour cet objectif.');return;}
  const payload={id:f.id.value,kind:f.kind.value,title:f.title.value,description:f.description.value,universe:f.universe.value,period:f.period.value,requirements:{metric,goal:metric==='cards'?ids.length:Number(f.goal.value),...(metric==='cards'?{card_ids:ids,edges:editing?.requirements?.card_ids?.join('|')===ids.join('|')?editing.requirements.edges:ids.slice(1).map((_,i)=>[i,i+1,f.relation.value])}:{}),...(metric==='universe'?{universe:f.universe.value}:{})},starts_at:f.starts_at.value?f.starts_at.value+':00Z':null,ends_at:f.ends_at.value?f.ends_at.value+':00Z':null,reward_kind:f.reward_kind.value,reward_label:f.reward_label.value,source_url:f.source_url.value,enabled:f.enabled.checked,secret:f.secret.checked,revision:editing?.revision||0};
  if(payload.starts_at&&payload.ends_at&&Date.parse(payload.ends_at)<=Date.parse(payload.starts_at)){status('La fin doit se situer après le début.');return;}
  const token=++epoch;busy=true;status('Enregistrement…');event.target.querySelector('button[type="submit"]').disabled=true;
  try{const r=await window.KizunaAccount.adventureRequest('definition_save',payload);if(token!==epoch||!allowed())return;definitions=r.definitions;editing=definitions.find(d=>d.id===payload.id);window.KizunaAdventure?.adminSaved(r);list();form();status('Définition enregistrée. '+(payload.enabled?'Elle est publiée.':'Elle est désactivée.'));}
  catch(e){if(token===epoch)status(/REVISION_CONFLICT/.test(e.message)?'Une autre personne a modifié cette définition. Actualise avant de continuer.':e.message);}
  finally{if(token===epoch){busy=false;root()?.querySelector('button[type="submit"]')?.removeAttribute('disabled');}}
 }
 new MutationObserver(mount).observe(document.querySelector('main'),{childList:true,subtree:true});document.addEventListener('kizuna:account-change',mount);mount();
})();
